// Independent ROUND2 review fixtures, pinned against the existing offline
// official jsonata@2.2.2. These desired outcomes deliberately remain failing
// until production repairs land. All evaluation uses the production self-exec
// worker; no evaluator bindings or controller-process evaluation are added.
// Reference observations and the four approved stronger-profile rejections are
// separate fields. Do not accept current false-UP output as a reference override.
func TestMatcherSortReviewReference(t *testing.T) {
	supported(t)
	var cases []struct {
		fixture
		Category       string `json:"category"`
		Classification string `json:"classification"`
		Want           string `json:"want"`
	}
	if err := json.Unmarshal([]byte(matcherSortReviewJSON), &cases); err != nil {
		t.Fatal(err)
	}
	if len(cases) != 105 {
		t.Fatal("independent matcher/sort review coverage missing")
	}
	safeDown := 0
	for _, f := range cases {
		switch f.Classification {
		case "reference":
			if f.Want != f.Reference.State {
				t.Fatal("reference expectation changed")
			}
		case "safe-profile":
			if f.Want != "down" || f.Reference.State != "up" {
				t.Fatal("approved profile divergence changed")
			}
			safeDown++
		default:
			t.Fatal("unclassified independent fixture")
		}
		t.Run(f.Category+"/"+f.Name, func(t *testing.T) {
			r := request(f.Expression, string(f.Expected))
			r.Document, r.Query.Operator = f.Document, f.Operator
			if err := r.Validate(); err != nil {
				t.Fatal(err)
			}
			got := Check(context.Background(), r)
			if got.State != f.Want || got.LatencyMs <= 0 || strings.Contains(got.Message, "private-marker") {
				t.Fatalf("state=%s want=%s message=%q latency=%g", got.State, f.Want, got.Message, got.LatencyMs)
			}
			if f.Want == "down" && got.Message != "service check failed" {
				t.Fatalf("expected fixed bounded failure: %+v", got)
			}
		})
	}
	if safeDown != 4 {
		t.Fatal("approved returned-comparator overflow controls missing")
	}
}

